insert into public.theories(id,title,summary,category_id,category_title,subcategory_id,taxonomy_order,canonical_id,legacy_ids,display_id,aliases,related_theory_ids,provenance,access_tier,status) values
('kb_909','社会的時計','就職、結婚、子育て、退職などを「何歳ごろに行うべきか」と社会が期待する時間表。周囲より遅れているという焦りは、能力だけでなく年齢への規範からも生まれる。文化や時代、生活条件で変わるため、自分の希望と社会の予定表を分けて考える。生物学的な体内時計とは異なる。','psychology','心理学','psychology-life',4,'kb_909','[]',336,'["social clock","ソーシャル・クロック","社会時計"]'::jsonb,'[]','{"status":"書誌確認済み","attribution":"Bernice L. Neugarten / Joan W. Moore / John C. Lowe","works":["Age Norms, Age Constraints, and Adult Socialization (1965)"],"sources":[{"title":"Age Norms, Age Constraints, and Adult Socialization (1965)","url":"https://www.journals.uchicago.edu/doi/10.1086/223965"}],"note":"年齢規範を扱う原著。特定年齢の出来事を全員に求める基準ではない。","period":"1965年（参照文献）"}'::jsonb,'complete','published'),
('kb_910','生涯発達理論','発達を子どもの成長だけでなく、生涯にわたる変化として捉える枠組み。能力や役割には伸びる側面と失われる側面が同時にあり、環境や歴史によって経路も変わる。年齢だけで可能性を決めず、今ある資源と学び直せる範囲を見る。あらゆる能力が無制限に向上するという意味ではない。','psychology','心理学','psychology-life',5,'kb_910','[]',337,'["life-span developmental psychology","ライフスパン発達心理学"]'::jsonb,'[]','{"status":"書誌確認済み","attribution":"Paul B. Baltes","works":["Theoretical Propositions of Life-Span Developmental Psychology: On the Dynamics Between Growth and Decline (1987)"],"sources":[{"title":"Theoretical Propositions of Life-Span Developmental Psychology: On the Dynamics Between Growth and Decline (1987)","url":"https://www.imprs-life.mpg.de/25277/022_baltes_1987.pdf"}],"note":"成長と衰退、多方向性、可塑性を含む枠組み。固定した年齢段階表ではない。"}'::jsonb,'complete','published'),
('kb_911','選択・最適化・補償モデル','限られた資源の中で、重視する目標を選び、その遂行を磨き、失われた手段を別の方法で補うという適応モデル。例えば活動を絞って練習し、補助道具を使って続ける。単なる諦めや効率化ではなく、本人にとって大切な活動を維持する見方である。補償がすべての損失を解消するとは限らない。','psychology','心理学','psychology-life',6,'kb_911','[]',338,'["SOCモデル","selective optimization with compensation"]'::jsonb,'[]','{"status":"書誌確認済み","attribution":"Paul B. Baltes","works":["On the incomplete architecture of human ontogeny: Selection, optimization, and compensation as foundation of developmental theory (1997)"],"sources":[{"title":"On the incomplete architecture of human ontogeny: Selection, optimization, and compensation as foundation of developmental theory (1997)","url":"https://pubmed.ncbi.nlm.nih.gov/9109347/"}],"note":"SOCの理論的整理を参照。成功した老いを単一尺度で決めない。"}'::jsonb,'complete','published'),
('kb_912','社会情動的選択性理論','残された時間をどう感じるかによって、人との関わりで優先する目標が変わるという理論。時間が広く開けていると知識や新しい縁を、限られていると意味ある関係や感情的充足を重視しやすい。暦年齢だけでなく時間の捉え方を見る。高齢者が必ず交流を減らすという法則ではない。','psychology','心理学','psychology-life',7,'kb_912','[]',339,'["socioemotional selectivity theory","SST","社会情緒的選択性理論"]'::jsonb,'[]','{"status":"書誌確認済み","attribution":"Laura L. Carstensen / Derek M. Isaacowitz / Susan T. Charles","works":["Taking time seriously: A theory of socioemotional selectivity (1999)"],"sources":[{"title":"Taking time seriously: A theory of socioemotional selectivity (1999)","url":"https://doi.org/10.1037/0003-066X.54.3.165"}],"note":"時間展望に関する理論。年齢と主観的な残り時間を区別する。"}'::jsonb,'complete','published'),
('kb_913','成人形成期','青年期を過ぎても成人の役割が定まらない時期を、仕事、恋愛、価値観を探索する発達上の期間として捉える考え方。進路の揺れを直ちに未熟さと決めず、試行の機会と生活条件を見直す手掛かりになる。教育や経済、文化に左右される枠組みで、すべての人が同じ年齢で経験する段階ではない。','psychology','心理学','psychology-life',8,'kb_913','[]',340,'["emerging adulthood","エマージング・アダルトフッド"]'::jsonb,'[]','{"status":"書誌確認済み","attribution":"Jeffrey Jensen Arnett","works":["Emerging adulthood: A theory of development from the late teens through the twenties (2000)"],"sources":[{"title":"Emerging adulthood: A theory of development from the late teens through the twenties (2000)","url":"https://pubmed.ncbi.nlm.nih.gov/10842426/"}],"note":"文化による条件差を含む理論。年齢から人格の成熟度を判定しない。"}'::jsonb,'complete','published'),
('kb_914','生態学的システム理論','発達を、家庭や学校といった身近な環境、そのつながり、職場や制度、文化などが重なって作用する過程として見る理論。本人の努力だけで説明できない変化を、環境の層ごとに考えられる。困り事を個人の性格に還元せず、支援先や環境調整を探す。後の生物生態学的モデルと完全な同義ではない。','psychology','心理学','psychology-life',9,'kb_914','[]',341,'["ecological systems theory","ブロンフェンブレンナーの生態学的理論"]'::jsonb,'[]','{"status":"書誌確認済み","attribution":"Urie Bronfenbrenner","works":["The Ecology of Human Development: Experiments by Nature and Design (1979)"],"sources":[{"title":"The Ecology of Human Development: Experiments by Nature and Design (1979)","url":"https://doi.org/10.4159/9780674028845"}],"note":"1979年の環境システムの枠組みを参照。後年のモデル拡張と区別。"}'::jsonb,'complete','published'),
('kb_915','ライフコース理論','人生の経路を、歴史的な時代、出来事が起きる時期、他者とのつながり、本人の選択の組み合わせで捉える枠組み。同じ転職や進学でも、それまでの経験と社会条件によって意味は変わる。人生を一律の年齢表で評価せず、転機の文脈を読む。自由な選択も制度や資源の制約の中で行われる。','psychology','心理学','psychology-life',10,'kb_915','[]',342,'["life course theory","ライフコース・アプローチ"]'::jsonb,'[]','{"status":"書誌確認済み","attribution":"Glen H. Elder Jr.","works":["The Life Course as Developmental Theory (1998)"],"sources":[{"title":"The Life Course as Developmental Theory (1998)","url":"https://doi.org/10.1111/j.1467-8624.1998.tb06128.x"}],"note":"社会的時間と結びついた人生の経路を扱う。生涯発達心理学とは説明の焦点が異なる。"}'::jsonb,'complete','published'),
('kb_916','流動性知能・結晶性知能','新しい課題の関係を見抜いて解く能力と、経験を通じて蓄積した知識を使う能力を区別する知能の枠組み。未知の道具の操作と、熟知した仕事の判断では求められる資源が異なる。年齢に伴う変化も一つの能力だけで測らない。二種類ですべての能力を説明できるわけではなく、個人差も大きい。','psychology','心理学','psychology-life',11,'kb_916','[]',343,'["fluid and crystallized intelligence","流動性知能","結晶性知能","Gf・Gc"]'::jsonb,'[]','{"status":"書誌確認済み","attribution":"Raymond B. Cattell","works":["Theory of fluid and crystallized intelligence: A critical experiment (1963)"],"sources":[{"title":"Theory of fluid and crystallized intelligence: A critical experiment (1963)","url":"https://doi.org/10.1037/h0046743"}],"note":"原著の書誌を確認。平均的な年齢傾向を個人の能力上限へ置き換えない。"}'::jsonb,'complete','published'),
('kb_917','脳の可塑性','経験や学習、環境の変化に応じて、神経系の働きや構造が変わりうる性質。成人でも技能練習に伴う変化が観察され、学び直しの可能性を支える。反復だけでなく課題、休息、環境を考える手掛かりになる。ただし変化の範囲には条件があり、努力すれば何でも治る、何歳でも同じ速度で習得できるという意味ではない。','psychology','心理学','psychology-n',1,'kb_917','[]',344,'["神経可塑性","脳可塑性","neuroplasticity","brain plasticity"]'::jsonb,'[]','{"status":"書誌確認済み","attribution":"Bogdan Draganskiほか（参照研究の著者）","works":["Changes in grey matter induced by training (2004)"],"sources":[{"title":"Changes in grey matter induced by training (2004)","url":"https://www.nature.com/articles/427311a"}],"note":"成人の学習に伴う構造変化の研究を参照。可塑性の唯一の初出でも万能な回復の証明でもない。"}'::jsonb,'complete','published'),
('kb_918','ヘッブの法則','ある神経細胞が別の細胞の活動を繰り返し助けると、その結びつきが強まるとする学習の仮説。経験を神経回路の変化として説明する基礎となった。複数の要素を一緒に学ぶ見方につながるが、日常の反復すべてが同じ神経機構で起きるわけではない。神経可塑性全体と同義にはせず、仮説と観察された現象を分ける。','psychology','心理学','psychology-n',2,'kb_918','[]',345,'["Hebbian learning","Hebbの法則","ヘッブ学習"]'::jsonb,'[]','{"status":"書誌確認済み","attribution":"Donald O. Hebb（原著）／T. V. P. Bliss / G. L. Collingridge（参照レビュー）","works":["The Organization of Behavior (1949); A synaptic model of memory: Long-term potentiation in the hippocampus (1993)"],"sources":[{"title":"The Organization of Behavior (1949); A synaptic model of memory: Long-term potentiation in the hippocampus (1993)","url":"https://www.nature.com/articles/361031a0"}],"note":"レビューに原著を参照する。通俗的な短句を原著の逐語引用とはしない。"}'::jsonb,'complete','published'),
('kb_919','長期増強','一定の活動の後に、神経細胞間の伝達の効き方が持続的に強くなる現象。学習や記憶を支えるシナプス変化を研究する重要なモデルとなった。練習と記憶の生物学的基盤を考える入口になるが、動物実験で観察された変化を、そのまま特定の勉強法の効果や人間のすべての記憶の説明にしない。','psychology','心理学','psychology-n',3,'kb_919','[]',346,'["long-term potentiation","LTP","シナプス長期増強"]'::jsonb,'[]','{"status":"書誌確認済み","attribution":"T. V. P. Bliss / G. L. Collingridge","works":["A synaptic model of memory: Long-term potentiation in the hippocampus (1993)"],"sources":[{"title":"A synaptic model of memory: Long-term potentiation in the hippocampus (1993)","url":"https://www.nature.com/articles/361031a0"}],"note":"原著の単なる紹介でなく機構を整理した参照レビュー。ヘッブの仮説と実験現象を区別する。"}'::jsonb,'complete','published'),
('kb_920','敏感期','特定の経験が神経系や能力の発達に強く影響しやすい期間。視覚や言語などで対象と時期が異なり、早期の環境が重要になる理由を考えられる。幼少期の機会を支える一方、時期を過ぎたら学習できないと一括して決めない。より厳しい条件を指す臨界期と区別し、すべての技能に同じ期限を当てはめない。','psychology','心理学','psychology-n',4,'kb_920','[]',347,'["sensitive period","感受性期"]'::jsonb,'[]','{"status":"書誌確認済み","attribution":"Eric I. Knudsen","works":["Sensitive periods in the development of the brain and behavior (2004)"],"sources":[{"title":"Sensitive periods in the development of the brain and behavior (2004)","url":"https://pubmed.ncbi.nlm.nih.gov/15509387/"}],"note":"敏感期と臨界期の概念差を保持。研究対象ごとに適用範囲が違う。"}'::jsonb,'complete','published'),
('kb_921','睡眠と記憶の固定化','学習した記憶が睡眠中の処理を通じて安定し、既存の知識と結びついていく過程。学んだ直後の成績と、後日使える状態を分けて考える助けになる。練習と睡眠の両方を学習計画に含める。効果は記憶の種類や睡眠の条件によって異なり、眠るだけで未学習の内容を覚えられるという意味ではない。','psychology','心理学','psychology-n',5,'kb_921','[]',348,'["sleep-dependent memory consolidation","睡眠依存性記憶固定"]'::jsonb,'[]','{"status":"書誌確認済み","attribution":"Björn Rasch / Jan Born","works":["About Sleep’s Role in Memory (2013)"],"sources":[{"title":"About Sleep’s Role in Memory (2013)","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3768102/"}],"note":"記憶の種類と睡眠段階による違いを整理したレビュー。睡眠中の新規学習の保証ではない。"}'::jsonb,'complete','published'),
('kb_922','アロスタティック負荷','ストレスに対処する身体の調整が繰り返され、終わりにくくなることで蓄積する負担を捉える概念。短期の適応に役立つ反応でも、長期にはコストを持ちうる。頑張る時間だけでなく回復や環境の負荷を見る手掛かりになる。主観的な疲れそのものや一つの診断名と同義ではなく、単一の指標だけで判定しない。','psychology','心理学','psychology-n',6,'kb_922','[]',349,'["allostatic load","アロスタシス負荷","アロスタティック・ロード"]'::jsonb,'[]','{"status":"書誌確認済み","attribution":"Bruce S. McEwen / Eliot Stellar","works":["Stress and the individual: Mechanisms leading to disease (1993)"],"sources":[{"title":"Stress and the individual: Mechanisms leading to disease (1993)","url":"https://pubmed.ncbi.nlm.nih.gov/8379800/"}],"note":"慢性・反復ストレスの身体的負荷の枠組み。個人への医学的診断基準として使わない。"}'::jsonb,'complete','published'),
('kb_923','ロミオとジュリエット効果','親などから恋愛を妨げられることが、かえって相手への思いを強める場合があるという仮説。自由を制限される反発との関連から説明されてきた。一方、後続の追試では同じ結果が支持されず、周囲の反対が関係を弱める場合もある。反対されるほど本当の愛だとは判断せず、反発と関係の安全性を分けて見る。','psychology','心理学','psychology-i',107,'kb_923','[]',271,'["ロミオ・ジュリエット効果","Romeo and Juliet effect","ロミオとジュリエット効果"]'::jsonb,'[]','{"status":"書誌確認済み","attribution":"Richard Driscoll / Keith E. Davis / Milton E. Lipetz（原研究）／H. Colleen Sinclair / Kristina B. Hood / Brittany L. Wright（追試）","works":["Parental interference and romantic love: The Romeo and Juliet effect (1972); Revisiting the Romeo and Juliet Effect (2014)"],"sources":[{"title":"原研究（1972）","url":"https://pubmed.ncbi.nlm.nih.gov/5079550/"},{"title":"追試・再検討（2014）","url":"https://doi.org/10.1027/1864-9335/a000181"}],"note":"原研究と2014年の追試を併記。普遍的・確定的な効果として扱わない。"}'::jsonb,'complete','published'),
('kb_924','成人愛着スタイル','親密な相手への安心感、見捨てられる不安、近づくことへの回避などの傾向を捉える枠組み。連絡頻度や距離の希望が違うとき、相手の悪意だけでなく関係で感じる不安を考えられる。乳幼児の愛着理論を成人の恋愛へ展開した研究に由来するが、自己診断で固定した性格や関係の運命を決めるものではない。','psychology','心理学','psychology-i',108,'kb_924','[]',272,'["adult attachment styles","成人の愛着スタイル","恋愛の愛着スタイル"]'::jsonb,'[]','{"status":"書誌確認済み","attribution":"Cindy Hazan / Phillip Shaver","works":["Romantic love conceptualized as an attachment process (1987)"],"sources":[{"title":"Romantic love conceptualized as an attachment process (1987)","url":"https://pubmed.ncbi.nlm.nih.gov/3572722/"}],"note":"成人の恋愛への展開を扱う。歴史的な類型と後の連続的な不安・回避の尺度を区別する。"}'::jsonb,'complete','published'),
('kb_925','接触仮説','異なる集団の人同士の接触が、偏見を減らしうるという仮説。対等な立場、共通目標、協力、制度の支えなど、接触の質が重要になる。違う世代や文化の人と協働する設計に役立つ。単に同じ場所へ集めればよいわけではなく、敵対的な経験は逆効果にもなりうる。単純接触効果とは対象と説明範囲が異なる。','psychology','心理学','psychology-v',29,'kb_925','[]',302,'["contact hypothesis","intergroup contact theory","集団間接触理論"]'::jsonb,'[]','{"status":"書誌確認済み","attribution":"Gordon W. Allport（提唱）／Thomas F. Pettigrew / Linda R. Tropp（参照研究）","works":["A Meta-Analytic Test of Intergroup Contact Theory (2006)"],"sources":[{"title":"A Meta-Analytic Test of Intergroup Contact Theory (2006)","url":"https://doi.org/10.1037/0022-3514.90.5.751"}],"note":"Allportの条件を参照し、メタ分析による検討を併記。条件を絶対的な必要条件とはしない。"}'::jsonb,'complete','published'),
('kb_926','現実的葛藤理論','集団同士が限られた資源や報酬を競うと、相手集団への敵意や偏見が強まりうるという理論。共同でしか達成できない上位目標は、関係を変える手掛かりになる。職場の対立では性格だけでなく報酬や予算の配分を見る。すべての偏見が資源競争だけで生じるわけではなく、集団の区分だけでも起こる影響と区別する。','psychology','心理学','psychology-v',30,'kb_926','[]',303,'["realistic conflict theory","現実的集団葛藤理論"]'::jsonb,'[]','{"status":"書誌確認済み","attribution":"Muzafer Sherif / O. J. Harvey / B. Jack White / William R. Hood / Carolyn W. Sherif","works":["Intergroup Conflict and Cooperation: The Robbers Cave Experiment (1961)"],"sources":[{"title":"Intergroup Conflict and Cooperation: The Robbers Cave Experiment (1961)","url":"https://psychclassics.yorku.ca/Sherif/index.htm"}],"note":"原報告の再録を参照。限られた実験参加者からあらゆる集団へ一般化しない。"}'::jsonb,'complete','published'),
('kb_927','ステレオタイプ内容モデル','集団への固定観念を、主に温かさと有能さの二つの評価軸で捉えるモデル。好意と能力の評価は同じ方向とは限らず、羨望や同情を含む複雑な偏見が生じる。人を「良い・悪い」の一軸で決める前に、何を推測しているかを振り返る。実際の能力や人格を判定する尺度ではなく、評価者側の認知を説明する。','psychology','心理学','psychology-v',31,'kb_927','[]',304,'["stereotype content model","SCM"]'::jsonb,'[]','{"status":"書誌確認済み","attribution":"Susan T. Fiske / Amy J. C. Cuddy / Peter Glick / Jun Xu","works":["A model of (often mixed) stereotype content: Competence and warmth respectively follow from perceived status and competition (2002)"],"sources":[{"title":"A model of (often mixed) stereotype content: Competence and warmth respectively follow from perceived status and competition (2002)","url":"https://pubmed.ncbi.nlm.nih.gov/12051578/"}],"note":"集団に対する知覚を説明するモデル。属性から個人の性質を決めつけない。"}'::jsonb,'complete','published'),
('kb_928','共感的正確性','相手が実際に考えたり感じたりしていることを、どれほど正確に推測できるかという概念。優しく接することや自分も同じ感情になることとは区別される。理解したつもりのときほど、推測を仮のものとして本人に確かめる。非言語的な手掛かりも使えるが、表情だけで内面を断定できるわけではない。','psychology','心理学','psychology-i',109,'kb_928','[]',273,'["empathic accuracy","共感的精度"]'::jsonb,'[]','{"status":"書誌確認済み","attribution":"William Ickes / Linda Stinson / Victor Bissonnette / Stella Garcia","works":["Naturalistic social cognition: Empathic accuracy in mixed-sex dyads (1990)"],"sources":[{"title":"Naturalistic social cognition: Empathic accuracy in mixed-sex dyads (1990)","url":"https://doi.org/10.1037/0022-3514.59.4.730"}],"note":"相手の報告と推測を比較する研究概念。思いやりや感情共有の程度と同一にしない。"}'::jsonb,'complete','published'),
('kb_929','演繹推論','前提が正しく、推論の形が妥当なら、結論も必ず成り立つ推論。「すべての提出物は署名が必要、この書類は提出物」から署名の必要性を導く。説明を読むときは前提の正しさと推論の妥当性を別々に確認する。結論が偶然正しいだけでは、そこへ至る理由まで正しいとは限らない。','strategy','戦略論','strategy-l',1,'kb_929','[]',85,'["deductive reasoning","演繹法"]'::jsonb,'[]','{"status":"書誌確認済み","attribution":"Nathan Smith（参照教材の著者）","works":["Introduction to Philosophy (2022), 5-3-arguments"],"sources":[{"title":"Introduction to Philosophy (2022), 5-3-arguments","url":"https://openstax.org/books/introduction-philosophy/pages/5-3-arguments"}],"note":"妥当性と前提の真偽の区別を参照。本文の例は独自作成。"}'::jsonb,'complete','published'),
('kb_930','帰納推論','観察した事例から、まだ観察していない事例や一般的な傾向を推測する推論。何度も同じ結果になった経験は予測を支えるが、次も必ず同じとは限らない。仕事の経験則を使うときは、事例の数と偏り、例外の条件を確認する。数学的帰納法とは意味が異なり、確率的な支持と論理的な保証を分ける。','strategy','戦略論','strategy-l',2,'kb_930','[]',86,'["inductive reasoning","帰納法"]'::jsonb,'[]','{"status":"書誌確認済み","attribution":"Nathan Smith（参照教材の著者）","works":["Introduction to Philosophy (2022), 5-3-arguments"],"sources":[{"title":"Introduction to Philosophy (2022), 5-3-arguments","url":"https://openstax.org/books/introduction-philosophy/pages/5-3-arguments"}],"note":"一般的な帰納推論を扱い、数学の証明法と区別する。"}'::jsonb,'complete','published'),
('kb_931','アブダクション','観察された事実を説明できる仮説を考え、候補の中から有力な説明を選ぶ推論。例えば遅延の原因を一つに決めず、設備、手順、情報の候補を比べる。新しい仮説を作る入口になるが、もっともらしい説明は真実の保証ではない。説明力、別の仮説、検証できる予測を照らし合わせる。','strategy','戦略論','strategy-l',3,'kb_931','[]',87,'["abduction","仮説的推論","最良の説明への推論"]'::jsonb,'[]','{"status":"書誌確認済み","attribution":"Igor Douven（参照論考の著者）","works":["Abduction, Stanford Encyclopedia of Philosophy"],"sources":[{"title":"Abduction, Stanford Encyclopedia of Philosophy","url":"https://plato.stanford.edu/entries/abduction/"}],"note":"仮説形成と最良の説明への推論を扱う論考。確実な証明とは区別。"}'::jsonb,'complete','published'),
('kb_932','反証可能性','主張が誤っているなら、どの観察によってそれが分かるかを示せる性質。成功しても失敗しても正しいと説明する主張は、経験による検討が難しい。計画では「何が起きたら仮説を見直すか」を先に決める。反証可能だから正しいとは限らず、一つの反例の解釈にも測定や補助仮定の吟味が必要になる。','strategy','戦略論','strategy-l',4,'kb_932','[]',88,'["falsifiability","反証主義"]'::jsonb,'[]','{"status":"書誌確認済み","attribution":"Karl R. Popper（理論）／Stephen Thornton（参照論考）","works":["Karl Popper, Stanford Encyclopedia of Philosophy"],"sources":[{"title":"Karl Popper, Stanford Encyclopedia of Philosophy","url":"https://plato.stanford.edu/entries/popper/"}],"note":"科学の境界をめぐる哲学的立場を参照。唯一の合意済み判定基準ではない。"}'::jsonb,'complete','published'),
('kb_933','相関と因果の区別','二つの事柄が一緒に変化することと、一方を変えると他方が変わることは別である。売上と会議回数が同時に増えても、需要など別の要因が両方を動かしている可能性がある。逆方向の因果や交絡も考え、介入や研究設計を確認する。相関が役立たないという意味ではなく、予測と原因の主張を分ける。','strategy','戦略論','strategy-l',5,'kb_933','[]',89,'["correlation and causation","相関は因果を意味しない"]'::jsonb,'[]','{"status":"書誌確認済み","attribution":"Judea Pearl","works":["Causal inference in statistics: An overview (2009)"],"sources":[{"title":"Causal inference in statistics: An overview (2009)","url":"https://doi.org/10.1214/09-SS057"}],"note":"相関と介入による因果の違いを整理した論考。本文の例は独自作成。"}'::jsonb,'complete','published'),
('kb_934','必要条件・十分条件','ある結果に欠かせない条件と、その条件があれば結果を保証する条件の区別。応募資格があっても採用が保証されるとは限らず、必要であることと十分であることを混同しない。「AならB」の逆が成り立つかは別に確認する。議論では、条件を満たさない例と満たしても結果が出ない例の両方を探す。','strategy','戦略論','strategy-l',6,'kb_934','[]',90,'["necessary and sufficient conditions","必要条件","十分条件"]'::jsonb,'[]','{"status":"書誌確認済み","attribution":"Nathan Smith（参照教材の著者）","works":["Introduction to Philosophy (2022), 5-2-logical-statements"],"sources":[{"title":"Introduction to Philosophy (2022), 5-2-logical-statements","url":"https://openstax.org/books/introduction-philosophy/pages/5-2-logical-statements"}],"note":"条件文の向きと条件の役割を参照。応募の例は独自作成。"}'::jsonb,'complete','published'),
('kb_935','人身攻撃の誤謬','主張への反論の代わりに、発言者の人格や属性を攻撃して主張を退ける推論の誤り。嫌いな人の提案でも、根拠は独立に検討する必要がある。議論では人の評価と内容の評価を分ける。ただし証言の信用や利益相反が論点に直接関係する場合、その確認まで常に誤謬になるわけではない。','strategy','戦略論','strategy-l',7,'kb_935','[]',91,'["ad hominem","人格攻撃"]'::jsonb,'[]','{"status":"書誌確認済み","attribution":"Nathan Smith（参照教材の著者）","works":["Introduction to Philosophy (2022), 5-5-informal-fallacies"],"sources":[{"title":"Introduction to Philosophy (2022), 5-5-informal-fallacies","url":"https://openstax.org/books/introduction-philosophy/pages/5-5-informal-fallacies"}],"note":"主張と関係のない人格攻撃を扱う。証言の信頼性の検討と区別する。"}'::jsonb,'complete','published'),
('kb_936','藁人形論法','相手の主張を弱い形や極端な形に置き換え、それを批判して元の主張を退けたように見せる論法。一部の改善案を「すべてを否定している」と言い換える場合などが当たる。反論の前に、相手が実際に言った範囲を確かめる。要約の違いをすべて故意の歪曲と決めつけず、理解を確認することも大切になる。','strategy','戦略論','strategy-l',8,'kb_936','[]',92,'["straw man fallacy","ストローマン論法","わら人形論法"]'::jsonb,'[]','{"status":"書誌確認済み","attribution":"Nathan Smith（参照教材の著者）","works":["Introduction to Philosophy (2022), 5-5-informal-fallacies"],"sources":[{"title":"Introduction to Philosophy (2022), 5-5-informal-fallacies","url":"https://openstax.org/books/introduction-philosophy/pages/5-5-informal-fallacies"}],"note":"誤った再構成への反論を扱う。本文の例は独自作成。"}'::jsonb,'complete','published'),
('kb_937','循環論法','証明したい結論を、既に正しいものとして前提に入れてしまう論法。「信頼できるから正しい、正しいから信頼できる」だけでは独立した根拠にならない。説明をたどり、結論を言い換えただけの理由がないか確認する。定義を置くこと自体とは区別し、その定義から現実についての正しさまで証明したと考えない。','strategy','戦略論','strategy-l',9,'kb_937','[]',93,'["circular reasoning"]'::jsonb,'[]','{"status":"書誌確認済み","attribution":"Nathan Smith（参照教材の著者）","works":["Introduction to Philosophy (2022), 5-5-informal-fallacies"],"sources":[{"title":"Introduction to Philosophy (2022), 5-5-informal-fallacies","url":"https://openstax.org/books/introduction-philosophy/pages/5-5-informal-fallacies"}],"note":"論点先取の一形態として循環を扱う。二つの概念が完全な同義という扱いではない。"}'::jsonb,'complete','published'),
('kb_938','シンプソンのパラドックス','集団別では同じ方向に見える割合の関係が、集計すると逆転することがある現象。構成比や条件の違いを無視した全体平均は、比較を誤らせうる。部署や利用者層の内訳を確認する手掛かりになる。ただし分ければ常に正しいわけではなく、何を比較したいかと因果関係に応じて集計方法を選ぶ必要がある。','strategy','戦略論','strategy-l',10,'kb_938','[]',94,'["Simpson’s paradox","Simpson paradox","Simpsonのパラドックス"]'::jsonb,'[]','{"status":"書誌確認済み","attribution":"Edward H. Simpson（原著）","works":["The Interpretation of Interaction in Contingency Tables (1951)"],"sources":[{"title":"The Interpretation of Interaction in Contingency Tables (1951)","url":"https://doi.org/10.1111/j.2517-6161.1951.tb00088.x"}],"note":"原著の現象と因果的な解釈を区別する。どの層を調整するかは研究設計に依存。"}'::jsonb,'complete','published'),
('kb_939','役割葛藤・役割曖昧性','両立しにくい期待を同時に求められる状態と、何を期待されているか分からない状態の区別。複数の上司の指示が衝突する場合と、担当範囲が決まっていない場合では必要な調整が異なる。優先順位、権限、評価基準を明確にする入口になる。本人の意欲不足だけに還元せず、職場の構造も確認する。','organization-management','組織・経営論','organization-management-i',25,'kb_939','[]',25,'["role conflict and role ambiguity","役割葛藤","役割曖昧性"]'::jsonb,'[]','{"status":"書誌確認済み","attribution":"John R. Rizzo / Robert J. House / Sidney I. Lirtzman","works":["Role Conflict and Ambiguity in Complex Organizations (1970)"],"sources":[{"title":"Role Conflict and Ambiguity in Complex Organizations (1970)","url":"https://doi.org/10.2307/2391486"}],"note":"異なる二概念を比較するカード。別名を同義とはみなさない。"}'::jsonb,'complete','published'),
('kb_940','努力報酬不均衡モデル','仕事へ投入する努力に対して、賃金、承認、安定性や昇進などの報酬が乏しい状態を、ストレスの要因として捉えるモデル。忙しさだけでなく報われ方を点検できる。個人の頑張り方に加え、待遇や評価の仕組みを検討する。病気の原因を一つに決める診断法ではなく、職務要求資源モデルとは着目する関係が異なる。','organization-management','組織・経営論','organization-management-i',26,'kb_940','[]',26,'["effort-reward imbalance model","ERIモデル","努力・報酬不均衡"]'::jsonb,'[]','{"status":"書誌確認済み","attribution":"Johannes Siegrist","works":["Adverse health effects of high-effort/low-reward conditions (1996)"],"sources":[{"title":"Adverse health effects of high-effort/low-reward conditions (1996)","url":"https://pubmed.ncbi.nlm.nih.gov/9547031/"}],"note":"原著モデルの書誌を参照。報酬は金銭だけに限定しない。"}'::jsonb,'complete','published'),
('kb_941','心理的エンパワーメント','仕事に意味があり、遂行でき、自分で選べ、結果へ影響を及ぼせると感じる状態を捉える枠組み。形式的に任せるだけでなく、本人が裁量と手応えを持てるかを見る。役割を渡すときは資源や情報、意思決定の余地も整える。権限委譲という制度そのものと同義ではなく、負担を増やすことだけでは高まらない。','organization-management','組織・経営論','organization-management-o',37,'kb_941','[]',86,'["psychological empowerment","心理的権限委譲"]'::jsonb,'[]','{"status":"書誌確認済み","attribution":"Gretchen M. Spreitzer","works":["Psychological Empowerment in the Workplace: Dimensions, Measurement, and Validation (1995)"],"sources":[{"title":"Psychological Empowerment in the Workplace: Dimensions, Measurement, and Validation (1995)","url":"https://webuser.bus.umich.edu/spreitze/Pdfs/PsychEmpowerment.pdf"}],"note":"意味、有能感、自己決定、影響の四側面を参照。制度と心理状態を区別する。"}'::jsonb,'complete','published'),
('kb_942','センスメイキング','曖昧な出来事について手掛かりを選び、言葉や行動を通じて、次に動ける理解を作っていく過程。障害や組織変更の場面では、何が起きているかの捉え方自体が行動を左右する。説明を共有しつつ新しい事実で更新する。もっともらしく話をまとめることと、原因を正確に検証したことは別に扱う。','organization-management','組織・経営論','organization-management-o',38,'kb_942','[]',87,'["sensemaking","意味づけの過程"]'::jsonb,'[]','{"status":"書誌確認済み","attribution":"Karl E. Weick / Kathleen M. Sutcliffe / David Obstfeld","works":["Organizing and the Process of Sensemaking (2005)"],"sources":[{"title":"Organizing and the Process of Sensemaking (2005)","url":"https://doi.org/10.1287/orsc.1050.0133"}],"note":"組織化との関係を整理した著者論考。説明のもっともらしさと事実の正確さを分ける。"}'::jsonb,'complete','published'),
('kb_943','フォッグ行動モデル','行動が起こるには、動機、実行のしやすさ、きっかけが同じ時点で揃うとする設計モデル。続かないときは意欲を責める前に、作業の難しさや合図の位置を調整する。例えば行動を小さくし、いつもの行動の後に置く。数式は設計の見方を表すもので、行動の発生を数値で必ず予測する法則ではない。','behavioral-science','行動科学','behavioral-science-h',13,'kb_943','[]',93,'["Fogg Behavior Model","FBM","B=MAP"]'::jsonb,'[]','{"status":"書誌確認済み","attribution":"B. J. Fogg","works":["Fogg Behavior Model（提唱者の現行解説）"],"sources":[{"title":"Fogg Behavior Model（提唱者の現行解説）","url":"https://www.behaviormodel.org/"}],"note":"現行のMotivation / Ability / Promptを参照。旧称Triggerとの名称変更を区別する。"}'::jsonb,'complete','published'),
('kb_944','行動変容ステージモデル','行動を変える準備を、無関心、関心、準備、実行、維持などの段階で捉えるモデル。まだ変える意図がない人と、実行後に続けたい人では支援の内容が違う。押しつける前に本人の準備や障壁を確認する。実際の変化は行き戻りがあり、あらゆる行動が同じ段階を必ず順番に通るわけではない。','behavioral-science','行動科学','behavioral-science-h',14,'kb_944','[]',94,'["transtheoretical model","TTM","トランスセオレティカル・モデル","変化のステージモデル"]'::jsonb,'[]','{"status":"書誌確認済み","attribution":"James O. Prochaska / Carlo C. DiClemente","works":["Stages and processes of self-change of smoking: Toward an integrative model of change (1983)"],"sources":[{"title":"Stages and processes of self-change of smoking: Toward an integrative model of change (1983)","url":"https://pubmed.ncbi.nlm.nih.gov/6863699/"}],"note":"禁煙の原研究と後のモデル拡張を区別。段階だけで介入の効果を保証しない。"}'::jsonb,'complete','published'),
('kb_945','馴化','同じ刺激を繰り返し経験すると、その刺激への反応が弱まりうる非連合学習。初めは気になった日常の物音に反応しにくくなる例がある。新しい環境での反応の変化を理解する手掛かりになる。感覚器の順応や疲労、強化がなくなる消去とは区別する。反復すればすべての恐怖や不快感が消えるとは限らない。','behavioral-science','行動科学','behavioral-science-l',17,'kb_945','[]',111,'["habituation","慣れの学習"]'::jsonb,'[]','{"status":"書誌確認済み","attribution":"Catharine H. Rankinほか","works":["Habituation revisited: An updated and revised description of the behavioral characteristics of habituation (2009)"],"sources":[{"title":"Habituation revisited: An updated and revised description of the behavioral characteristics of habituation (2009)","url":"https://pubmed.ncbi.nlm.nih.gov/18854219/"}],"note":"非連合学習の研究上の定義。疲労・感覚順応・消去とは区別する。"}'::jsonb,'complete','published'),
('kb_946','鋭敏化','強い刺激などの経験後に、後続の刺激への反応が強くなることがある非連合学習。反復していれば必ず慣れるとは限らず、刺激の強さや経験によって逆方向の変化も起こる。試す負荷を調整し、反応の変化を見ながら進む。馴化の反対概念として理解できるが、両者は同じ場面で並行して作用することもある。','behavioral-science','行動科学','behavioral-science-l',18,'kb_946','[]',112,'["sensitization","感作"]'::jsonb,'[]','{"status":"書誌確認済み","attribution":"Richard F. Thompson / William A. Spencer","works":["Habituation: A model phenomenon for the study of neuronal substrates of behavior (1966)"],"sources":[{"title":"Habituation: A model phenomenon for the study of neuronal substrates of behavior (1966)","url":"https://pubmed.ncbi.nlm.nih.gov/5324565/"}],"note":"非連合学習の機構を扱う原著レビュー。強い刺激への反応を一律の臨床判断へ置き換えない。"}'::jsonb,'complete','published'),
('kb_947','学習性勤勉さ','努力を要する活動で報われる経験が、努力そのものへの抵抗を弱め、別の課題での粘り強さにもつながりうるという理論。才能や根性だけで継続を説明せず、難しさと成果の結びつきを考える。無理を長く続ければよいという教訓ではなく、報酬の与え方や課題の条件によって転移は異なる。','behavioral-science','行動科学','behavioral-science-l',19,'kb_947','[]',113,'["learned industriousness","学習性勤勉性"]'::jsonb,'[]','{"status":"書誌確認済み","attribution":"Robert Eisenberger","works":["Learned Industriousness (1992)／提唱者による理論の説明"],"sources":[{"title":"Learned Industriousness (1992)／提唱者による理論の説明","url":"https://www1.udel.edu/psych/fingerle/eisenber.htm"}],"note":"提唱者自身の説明と原著の書誌を参照。努力正当化とは異なる理論。"}'::jsonb,'complete','published'),
('kb_948','足場かけ','学習者が一人では難しい課題へ取り組めるよう、必要な部分を支援し、できるようになるにつれて支援を減らす方法。手順の一部を示し、残りを本人が試すような支援が含まれる。教える側がすべてを代行せず、本人の理解に合わせる。最近接発達領域は学べる範囲の概念であり、足場かけという支援方法と同義ではない。','behavioral-science','行動科学','behavioral-science-l',20,'kb_948','[]',114,'["scaffolding","スキャフォールディング"]'::jsonb,'[]','{"status":"書誌確認済み","attribution":"David Wood / Jerome S. Bruner / Gail Ross","works":["The role of tutoring in problem solving (1976)"],"sources":[{"title":"The role of tutoring in problem solving (1976)","url":"https://pubmed.ncbi.nlm.nih.gov/932126/"}],"note":"支援の機能を扱う原研究。発達領域という説明概念と区別する。"}'::jsonb,'complete','published'),
('kb_949','ダモクレスの剣','栄華を味わうダモクレスの頭上に、細い毛で吊られた剣が置かれるという古典の寓話。外からは恵まれて見える地位にも、常に危険や恐れが伴いうることを示す。成功を羨むときは、その人の責任や失うものも考える。実験で確認された心理効果ではなく、権力と幸福を考えるための比喩として読む。','classics-thought','古典・思想','classics-thought-w',17,'kb_949','[]',32,'["Sword of Damocles","ダモクレスのつるぎ"]'::jsonb,'[]','{"status":"書誌確認済み","attribution":"Marcus Tullius Cicero（伝承を記した著者）","works":["Tusculanae Disputationes, Book V, 61–62"],"sources":[{"title":"Tusculanae Disputationes, Book V, 61–62","url":"https://www.perseus.tufts.edu/hopper/text?doc=Perseus%3Atext%3A2007.01.0044%3Abook%3D5"}],"note":"キケロによる伝承の記述を参照。本人が寓話を創作したと断定しない。","period":"紀元前45年ごろ（著作）"}'::jsonb,'complete','published'),
('kb_950','洞窟の比喩','洞窟の壁に映る影しか見ていない人々を通じて、見慣れたものを真実の全体だと思い込む危うさを描く比喩。教育や認識の転換には、慣れた見方から離れる難しさが伴う。情報を読むときは、自分が見ている範囲と外にある条件を考える。自分だけが真実を知ると宣言する根拠にはしない。','classics-thought','古典・思想','classics-thought-w',18,'kb_950','[]',33,'["allegory of the cave","プラトンの洞窟"]'::jsonb,'[]','{"status":"書誌確認済み","attribution":"Plato","works":["Republic, Book VII, 514a–520a"],"sources":[{"title":"Republic, Book VII, 514a–520a","url":"https://classics.mit.edu/Plato/republic.8.vii.html"}],"note":"原著の英訳を参照。心理学の実験効果とは区別する。"}'::jsonb,'complete','published'),
('kb_951','テセウスの船','船の部材を順に交換し、すべてが新しくなっても同じ船と言えるかを問う同一性の問題。材料、形、機能、歴史の連続性など、何を同じとみなすかで答えは変わる。組織や自分が変化したとき、何を受け継ぎたいかを考える入口になる。特定の答えが実験で証明された問題ではなく、基準を明らかにする思考実験である。','classics-thought','古典・思想','classics-thought-w',19,'kb_951','[]',34,'["Ship of Theseus","テセウスのパラドックス"]'::jsonb,'[]','{"status":"書誌確認済み","attribution":"Plutarch（古典の記述）","works":["Life of Theseus, 23.1"],"sources":[{"title":"Life of Theseus, 23.1","url":"https://www.perseus.tufts.edu/hopper/text?doc=Perseus%3Atext%3A2008.01.0067%3Achapter%3D23%3Asection%3D1"}],"note":"部材交換についての原典を参照。後世の拡張した設定とは区別する。"}'::jsonb,'complete','published'),
('kb_952','ソクラテス式問答法','答えを一方的に教えるのでなく、問いを重ねて定義や前提、考え同士の整合性を検討する対話の方法。例えば「良い判断とは何か」を具体例と反例で確かめる。分かったつもりの言葉をほどく助けになるが、相手を追い詰める詰問とは区別する。現代の教育や臨床への応用は、古代の対話と同一ではない。','classics-thought','古典・思想','classics-thought-w',20,'kb_952','[]',35,'["Socratic method","ソクラテス問答","エレンコス"]'::jsonb,'[]','{"status":"書誌確認済み","attribution":"Plato（ソクラテスの対話を描いた著者）","works":["Euthyphro"],"sources":[{"title":"Euthyphro","url":"https://classics.mit.edu/Plato/euthyfro.html"}],"note":"原著の英訳に見られる反駁の対話を参照。現代の各技法をすべてソクラテス本人に帰属しない。"}'::jsonb,'complete','published'),
('kb_953','アリストテレスの中庸','徳を過剰と不足の間にある、状況にふさわしいあり方として捉える考え方。勇気は無謀でも臆病でもなく、何を恐れどう行動するかの判断を含む。両極端を避けるだけでなく、目的、相手、時機を考える。単なる平均や妥協ではなく、どんな行為にも善い中間があるとする主張でもない。','classics-thought','古典・思想','classics-thought-w',21,'kb_953','[]',36,'["doctrine of the mean","徳としての中庸"]'::jsonb,'[]','{"status":"書誌確認済み","attribution":"Aristotle","works":["Nicomachean Ethics, Book II"],"sources":[{"title":"Nicomachean Ethics, Book II","url":"https://classics.mit.edu/Aristotle/nicomachaen.2.ii.html"}],"note":"東洋思想の中庸や選択の妥協効果とは別カード。訳文を転載せず説明する。"}'::jsonb,'complete','published'),
('kb_954','定言命法','特定の欲望を実現するための条件つき命令と区別し、無条件に従うべき道徳原理を考えるカントの概念。自分の行動規則を誰もが用いてよいか、人を単なる手段として扱っていないかを問う。目的のために例外を作る前に規則を点検する。道徳哲学上の立場であり、社会で必ず支持される行動の予測法ではない。','classics-thought','古典・思想','classics-thought-w',22,'kb_954','[]',37,'["categorical imperative","カントの定言命法"]'::jsonb,'[]','{"status":"書誌確認済み","attribution":"Immanuel Kant","works":["Groundwork of the Metaphysics of Morals (1785)"],"sources":[{"title":"Groundwork of the Metaphysics of Morals (1785)","url":"https://www.gutenberg.org/files/5682/5682-h/5682-h.htm"}],"note":"原著の英訳を参照。仮言命法と区別し、他の倫理学の唯一の答えとしない。"}'::jsonb,'complete','published'),
('kb_955','功利主義','行動や制度を、それによって生じる幸福や苦痛などの帰結から評価する倫理学の立場。自分の利益だけでなく影響を受ける人々の利益を考える。選択肢を比べるときは、誰に何が起きるかを広く見る。単なる多数決や目先の得と同義ではなく、利益の測り方や権利の扱いをめぐって議論がある。','classics-thought','古典・思想','classics-thought-w',23,'kb_955','[]',38,'["utilitarianism","最大幸福原理"]'::jsonb,'[]','{"status":"書誌確認済み","attribution":"John Stuart Mill（参照著作の著者）","works":["Utilitarianism, Chapter II"],"sources":[{"title":"Utilitarianism, Chapter II","url":"https://www.gutenberg.org/files/11224/11224-h/11224-h.htm"}],"note":"ミルの著作を参照。功利主義全体を唯一の著者に帰属せず、思想と心理効果を区別する。"}'::jsonb,'complete','published'),
('kb_956','無知のヴェール','自分が社会でどの地位、能力、境遇に置かれるかを知らない立場から、公正な制度の原則を考える思考実験。ルールを決める際、得をする側にいるという前提を外して見直す手掛かりになる。実際に全情報を捨てる方法ではなく、ロールズの正義論で用いる仮定である。公平感の心理モデルや功利主義とは区別する。','classics-thought','古典・思想','classics-thought-w',24,'kb_956','[]',39,'["veil of ignorance","無知のベール"]'::jsonb,'[]','{"status":"書誌確認済み","attribution":"John Rawls","works":["A Theory of Justice (1971), §§24–25"],"sources":[{"title":"A Theory of Justice (1971), §§24–25","url":"https://doi.org/10.4159/9780674042605"}],"note":"原著の書誌を参照。原初状態という設定の中の情報制約として扱う。"}'::jsonb,'complete','published');
