 if (select count(*) from public.theories where status='published' and access_tier='free')<>151 then raise exception 'Free count mismatch';end if;
 if exists(select 1 from public.theories t join public.theory_taxonomy_backups b on b.source_id=t.id and b.source_table='theories' and b.migration_key='theory-coverage-20261015' where t.title is distinct from (b.snapshot->>'title') or t.summary is distinct from (b.snapshot->>'summary') or t.provenance is distinct from nullif(b.snapshot->'provenance','null'::jsonb) or t.access_tier is distinct from (b.snapshot->>'access_tier') or not (t.related_theory_ids @> (b.snapshot->'related_theory_ids'))) then raise exception 'Existing content changed';end if;
 if exists(select 1 from public.theories t left join public.theory_subcategories s on s.id=t.subcategory_id where t.status='published' and (s.id is null or s.category_id<>t.category_id)) then raise exception 'Classification mismatch';end if;
 if exists(select 1 from public.theories where status='published' group by subcategory_id having min(taxonomy_order)<>1 or max(taxonomy_order)<>count(*) or count(distinct taxonomy_order)<>count(*)) then raise exception 'Section order mismatch';end if;
 if exists(select 1 from (select t.display_id,row_number() over(partition by t.category_id order by s.display_order,t.taxonomy_order,t.id) expected from public.theories t join public.theory_subcategories s on s.id=t.subcategory_id where t.status='published') x where x.display_id<>x.expected) then raise exception 'Display order mismatch';end if;
 if exists(select 1 from public.theories t left join public.paid_content p on p.content_type='theory' and p.content_id=t.id where t.status='published' and t.access_tier='complete' and (p.content_id is null or p.payload->>'summary' is distinct from t.summary or p.payload->>'subcategoryId' is distinct from t.subcategory_id or (p.payload->>'displayId')::integer is distinct from t.display_id)) then raise exception 'Paid projection mismatch';end if;
end $verify$;
commit;
